package main

import "html/template"

var phoneTemplate = template.Must(template.New("phone").Parse(`<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light"><title>ファイル転送</title>
<style>
:root{--text:#202124;--sub:#6b7280;--line:#e5e7eb;--blue:#2563eb;--good:#166534}*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:680px;margin:0 auto;padding:38px 20px 70px}h1{font-size:30px;margin:0 0 8px}h2{font-size:21px;margin:0 0 6px}.lead,.muted{color:var(--sub);line-height:1.6}.notice{margin:22px 0;padding:11px 13px;background:#fafafa;border-left:3px solid #d1d5db}.section{padding:30px 0;border-top:1px solid var(--line)}.label{font-size:13px;font-weight:700;color:var(--sub);margin-bottom:8px}.fileLabel,.btn,.download{display:inline-block;border:1px solid var(--line);border-radius:6px;padding:11px 14px;font-size:15px;font-weight:650;text-decoration:none;cursor:pointer}.fileLabel{background:var(--blue);border-color:var(--blue);color:#fff}.fileLabel input{display:none}.btn{background:#fff;color:var(--text)}.row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.name{flex:1;min-width:0;overflow-wrap:anywhere}.size{font-size:12px;color:var(--sub);margin-top:3px}.download{background:#fff;color:var(--blue)}.progress{display:none;margin-top:14px}.bar{height:6px;background:#eee;border-radius:999px;overflow:hidden}.bar div{height:100%;width:0;background:var(--blue)}.status{margin-top:8px;color:var(--sub);font-size:14px}.ok{color:var(--good)}.empty{color:var(--sub);padding:12px 0}.foot{font-size:12px;color:var(--sub);margin-top:30px}
</style></head><body><main class="wrap"><h1>ファイル転送</h1><div class="lead">{{.DeviceName}} とファイルを送受信できます。</div><div class="notice">Wi‑Fiに「インターネットなし」と表示されても正常です。転送が終わるまでこのページを閉じないでください。</div>
<section class="section"><div class="label">スマホ → PC</div><h2>PCへ送る</h2><div class="muted">1ファイル最大 {{.MaxMB}} MBです。</div><div style="margin-top:16px"><label class="fileLabel">ファイルを選ぶ<input id="pick" type="file" multiple></label></div><div id="progress" class="progress"><div id="pname" class="status"></div><div class="bar"><div id="pbar"></div></div><div id="ptext" class="status"></div></div><div id="result" class="status"></div></section>
<section class="section"><div class="label">PC → スマホ</div><h2>スマホで受け取る</h2><div class="muted">PC側で用意されたファイルが表示されます。</div><div style="margin:14px 0"><button class="btn" onclick="loadFiles()">一覧を更新</button></div><div id="files"><div class="empty">確認中...</div></div></section>
<div class="foot">このページは今回のセッションだけ有効です。</div></main>
<script>
const base='/s/{{.Token}}',pick=document.getElementById('pick');function fmt(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}
pick.addEventListener('change',async()=>{for(const f of pick.files)await upload(f);pick.value='';loadFiles()});
function upload(file){return new Promise(resolve=>{const x=new XMLHttpRequest(),box=document.getElementById('progress'),bar=document.getElementById('pbar'),txt=document.getElementById('ptext'),name=document.getElementById('pname'),res=document.getElementById('result');box.style.display='block';name.textContent='送信中: '+file.name;bar.style.width='0';txt.textContent='準備中...';res.textContent='';x.upload.onprogress=e=>{if(e.lengthComputable){const p=Math.round(e.loaded/e.total*100);bar.style.width=p+'%';txt.textContent=p+'%'}};x.onload=()=>{if(x.status>=200&&x.status<300){res.textContent='送信しました: '+file.name;res.className='status ok'}else{res.textContent=x.responseText||'送信できませんでした';res.className='status'}resolve()};x.onerror=()=>{res.textContent='通信エラーが発生しました';resolve()};x.open('POST',base+'/upload?name='+encodeURIComponent(file.name));x.setRequestHeader('Content-Type','application/octet-stream');x.send(file)})}
async function loadFiles(){const box=document.getElementById('files');try{const r=await fetch(base+'/api/files',{cache:'no-store'});if(!r.ok)throw 0;const fs=await r.json();if(!fs.length){box.innerHTML='<div class="empty">今は受け取れるファイルがありません。</div>';return}box.innerHTML='';for(const f of fs){const d=document.createElement('div');d.className='row';const n=document.createElement('div');n.className='name';const strong=document.createElement('strong');strong.textContent=f.name;const size=document.createElement('div');size.className='size';size.textContent=fmt(f.size);n.append(strong,size);const a=document.createElement('a');a.className='download';a.textContent='受け取る';a.href=base+'/download/'+encodeURIComponent(f.id);d.append(n,a);box.appendChild(d)}}catch(e){box.innerHTML='<div class="empty">接続が終了した可能性があります。</div>'}}
loadFiles();setInterval(loadFiles,5000);
</script></body></html>`))
